  public static func add(RECHECK_STATUS: dcoRecheckOutcome, _ fbb: inout FlatBufferBuilder) { fbb.add(element: RECHECK_STATUS.rawValue, def: 0, at: VT.RECHECK_STATUS) }
  public static func add(RECHECK_NOTES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RECHECK_NOTES, at: VT.RECHECK_NOTES) }
  public static func addVectorOf(ATTRIBUTIONS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ATTRIBUTIONS, at: VT.ATTRIBUTIONS) }
  public static func endDCO(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); fbb.require(table: end, fields: [4, 6, 8, 10, 12]); return end }
  public static func createDCO(
    _ fbb: inout FlatBufferBuilder,
    DCO_IDOffset DCO_ID: Offset,
    COA_IDOffset COA_ID: Offset,
    TMX_RUN_IDOffset TMX_RUN_ID: Offset,
    CREATED_UTCOffset CREATED_UTC: Offset,
    THREAT_REFOffset THREAT_REF: Offset,
    ACTION_KIND: dcoActionKind = .unspecified,
    NORAD_CAT_ID: UInt32 = 0,
    GROUP_IDOffset GROUP_ID: Offset = Offset(),
    DELTA_V_MPS: Double = 0.0,
    PROPELLANT_KG: Double = 0.0,
    MISSION_LIFE_DAYS: Double = 0.0,
    OUTAGE_HOURS: Double = 0.0,
    COVERAGE_IMPACT_PCT: Double = 0.0,
    MARGIN_GAIN_DB: Double = 0.0,
    EXPOSURE_REDUCED_MIN: Double = 0.0,
    BASELINE_SCORE: UInt16 = 0,
    RESIDUAL_SCORE: UInt16 = 0,
    RESIDUAL_TIER: dcoSeverityLevel = .unavailable,
    CONFLICTS_WITH_COA_IDSVectorOffset CONFLICTS_WITH_COA_IDS: Offset = Offset(),
    SECONDARY_THREATS_INTRODUCEDVectorOffset SECONDARY_THREATS_INTRODUCED: Offset = Offset(),
    RECHECKED: Bool = false,
    RECHECK_STATUS: dcoRecheckOutcome = .unchecked,
    RECHECK_NOTESOffset RECHECK_NOTES: Offset = Offset(),
    ATTRIBUTIONSVectorOffset ATTRIBUTIONS: Offset = Offset()
  ) -> Offset {
    let __start = DCO.startDCO(&fbb)
    DCO.add(DCO_ID: DCO_ID, &fbb)
    DCO.add(COA_ID: COA_ID, &fbb)
    DCO.add(TMX_RUN_ID: TMX_RUN_ID, &fbb)
    DCO.add(CREATED_UTC: CREATED_UTC, &fbb)
    DCO.add(THREAT_REF: THREAT_REF, &fbb)
    DCO.add(ACTION_KIND: ACTION_KIND, &fbb)
    DCO.add(NORAD_CAT_ID: NORAD_CAT_ID, &fbb)
    DCO.add(GROUP_ID: GROUP_ID, &fbb)
    DCO.add(DELTA_V_MPS: DELTA_V_MPS, &fbb)
    DCO.add(PROPELLANT_KG: PROPELLANT_KG, &fbb)
    DCO.add(MISSION_LIFE_DAYS: MISSION_LIFE_DAYS, &fbb)
    DCO.add(OUTAGE_HOURS: OUTAGE_HOURS, &fbb)
    DCO.add(COVERAGE_IMPACT_PCT: COVERAGE_IMPACT_PCT, &fbb)
    DCO.add(MARGIN_GAIN_DB: MARGIN_GAIN_DB, &fbb)
    DCO.add(EXPOSURE_REDUCED_MIN: EXPOSURE_REDUCED_MIN, &fbb)
    DCO.add(BASELINE_SCORE: BASELINE_SCORE, &fbb)
    DCO.add(RESIDUAL_SCORE: RESIDUAL_SCORE, &fbb)
    DCO.add(RESIDUAL_TIER: RESIDUAL_TIER, &fbb)
    DCO.addVectorOf(CONFLICTS_WITH_COA_IDS: CONFLICTS_WITH_COA_IDS, &fbb)
    DCO.addVectorOf(SECONDARY_THREATS_INTRODUCED: SECONDARY_THREATS_INTRODUCED, &fbb)
    DCO.add(RECHECKED: RECHECKED, &fbb)
    DCO.add(RECHECK_STATUS: RECHECK_STATUS, &fbb)
    DCO.add(RECHECK_NOTES: RECHECK_NOTES, &fbb)
    DCO.addVectorOf(ATTRIBUTIONS: ATTRIBUTIONS, &fbb)
    return DCO.endDCO(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.DCO_ID, fieldName: "DCO_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.COA_ID, fieldName: "COA_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.TMX_RUN_ID, fieldName: "TMX_RUN_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.CREATED_UTC, fieldName: "CREATED_UTC", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.THREAT_REF, fieldName: "THREAT_REF", required: true, type: ForwardOffset<DCOThreatRef>.self)
    try _v.visit(field: VT.ACTION_KIND, fieldName: "ACTION_KIND", required: false, type: dcoActionKind.self)
    try _v.visit(field: VT.NORAD_CAT_ID, fieldName: "NORAD_CAT_ID", required: false, type: UInt32.self)
    try _v.visit(field: VT.GROUP_ID, fieldName: "GROUP_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.DELTA_V_MPS, fieldName: "DELTA_V_MPS", required: false, type: Double.self)
    try _v.visit(field: VT.PROPELLANT_KG, fieldName: "PROPELLANT_KG", required: false, type: Double.self)
    try _v.visit(field: VT.MISSION_LIFE_DAYS, fieldName: "MISSION_LIFE_DAYS", required: false, type: Double.self)
    try _v.visit(field: VT.OUTAGE_HOURS, fieldName: "OUTAGE_HOURS", required: false, type: Double.self)
    try _v.visit(field: VT.COVERAGE_IMPACT_PCT, fieldName: "COVERAGE_IMPACT_PCT", required: false, type: Double.self)
    try _v.visit(field: VT.MARGIN_GAIN_DB, fieldName: "MARGIN_GAIN_DB", required: false, type: Double.self)
    try _v.visit(field: VT.EXPOSURE_REDUCED_MIN, fieldName: "EXPOSURE_REDUCED_MIN", required: false, type: Double.self)
    try _v.visit(field: VT.BASELINE_SCORE, fieldName: "BASELINE_SCORE", required: false, type: UInt16.self)
    try _v.visit(field: VT.RESIDUAL_SCORE, fieldName: "RESIDUAL_SCORE", required: false, type: UInt16.self)
    try _v.visit(field: VT.RESIDUAL_TIER, fieldName: "RESIDUAL_TIER", required: false, type: dcoSeverityLevel.self)
    try _v.visit(field: VT.CONFLICTS_WITH_COA_IDS, fieldName: "CONFLICTS_WITH_COA_IDS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.SECONDARY_THREATS_INTRODUCED, fieldName: "SECONDARY_THREATS_INTRODUCED", required: false, type: ForwardOffset<Vector<ForwardOffset<DCOThreatRef>, DCOThreatRef>>.self)
    try _v.visit(field: VT.RECHECKED, fieldName: "RECHECKED", required: false, type: Bool.self)
    try _v.visit(field: VT.RECHECK_STATUS, fieldName: "RECHECK_STATUS", required: false, type: dcoRecheckOutcome.self)
    try _v.visit(field: VT.RECHECK_NOTES, fieldName: "RECHECK_NOTES", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ATTRIBUTIONS, fieldName: "ATTRIBUTIONS", required: false, type: ForwardOffset<Vector<ForwardOffset<DCOModuleAttribution>, DCOModuleAttribution>>.self)
    _v.finish()
  }
}
